"use server"

// Server action to handle chat messages securely
export async function sendChatMessage(messageText: string): Promise<string> {
  try {
    const webhookUrl = process.env.NEXT_PUBLIC_CHAT_WEBHOOK_URL

    if (!webhookUrl) {
      throw new Error("Webhook URL not configured")
    }

    const response = await fetch(webhookUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        // If you need API key authentication, use a server-side env var:
        // 'Authorization': `Bearer ${process.env.API_KEY}`,
      },
      body: JSON.stringify({
        message: messageText,
        timestamp: new Date().toISOString(),
      }),
    })

    if (!response.ok) {
      throw new Error(`Webhook returned status ${response.status}`)
    }

    const data = await response.json()

    // Parse response based on common formats
    return data.response || data.message || data.text || "Извините, не удалось получить ответ"
  } catch (err) {
    console.error("[v0] Server action error:", err)
    throw new Error("Не удалось связаться с сервером. Пожалуйста, попробуйте позже.")
  }
}
